/// <summary>
/// Gets the [recordExists, sequenceNumber]; preserves missing versus zero
/// </summary>
/// <param name = "_warehouse">Warehouse value</param>
/// <param name = "_customer">Customer value</param>
/// <returns>Returns sequenceNumber.</returns>
public static container sequenceNumber(InventLocationId _warehouse, CustAccount _customer)
{
    METCSDCustPickingSequence sequence;
    int matches;
    int64 result;

    while select SequenceNumber from sequence
        where sequence.InventLocationId == _warehouse
           && sequence.CustAccount == _customer
    {
        matches++;
        if (matches > 1)
        {
            throw error(strFmt("@MET:METSequenceNumValidate",
                curext(), _warehouse, _customer));
        }
        result = sequence.SequenceNumber;
    }
    return [matches == 1, result];
}

/// <summary>
/// Reads the existing attribute entity, including its inherited text mapping
/// </summary>
/// <param name = "_company">Legal entity</param>
/// <param name = "_customer">Customer account</param>
/// <returns>Return tote type</returns>
public static str toteType(DataAreaId _company, CustAccount _customer)
{
    CustomerAttributeValueEntity attributeValue;
    int matches;
    str textValue;

    while select TextValue from attributeValue
        where attributeValue.CustomerDataAreaId == _company
           && attributeValue.AccountNum == _customer
           && attributeValue.AttributeName == 'Tote type'
    {
        matches++;
        if (matches > 1)
        {
            throw error(strFmt("@MET:METToteTypeValidate",
                _company, _customer));
        }
        textValue = attributeValue.TextValue;
    }

    switch (textValue)
    {
        case '':
        case 'Blank':
        case 'N - None':
            return '';
        case 'C- Cardboard':
            return 'C';
        case 'P - Plastic':
            return 'P';
        default:
            throw error(strFmt("@MET:METToteTypeSupported",
                textValue, _company, _customer));
    }
}

/// <summary>
/// Resolve settings for the shipping site and fetch the optional MET value in one query.
/// </summary>
/// <param name = "_item">Item number</param>
/// <param name = "_shippingSite">Shipping site</param>
/// <returns>Returns item type</returns>
public static str itemType(ItemId _item, InventSiteId _shippingSite)
{
    InventItemInventSetup settings;
    InventDim settingsDim;
    METInventItemOrderSetup metSettings;
    int matches;
    str result;
    if (!_item || !_shippingSite)
    {
        return '';
    }
    while select InventDimId from settings
        where settings.ItemId == _item
        join RecId from settingsDim
            where settingsDim.InventDimId == settings.InventDimId
               && settingsDim.InventSiteId == _shippingSite
        outer join ItemType from metSettings
            where metSettings.ItemId == settings.ItemId
               && metSettings.InventDimId == settings.InventDimId
    {
        matches++;
        if (matches > 1)
        {
            throw error(strFmt(
                "@MET:METItemTypeValidate",
                curext(), _item, _shippingSite));
        }
        result = metSettings.ItemType;
    }
    return result;
}

/// <summary>
/// Resolve coverage and fetch the optional MET value in one query.
/// </summary>
/// <param name = "_item">Item number</param>
/// <param name = "_warehouse">Warehouse</param>
/// <returns>Returns slot location area</returns>
public static str slotLocationArea(ItemId _item, InventLocationId _warehouse)
{
    ReqItemTable coverage;
    InventDim coverageDim;
    METReqItemTable metCoverage;
    int matches;
    str result;
    while select RecId from coverage
        where coverage.ItemId == _item
        join RecId from coverageDim
            where coverageDim.InventDimId == coverage.CovInventDimId
               && coverageDim.InventLocationId == _warehouse
        outer join SlotLoc1Area from metCoverage
            where metCoverage.RefRecId == coverage.RecId
    {
        matches++;
        if (matches > 1)
        {
            throw error(strFmt("@MET:METSlotValidate",
                curext(), _item, _warehouse));
        }
        result = metCoverage.SlotLoc1Area;
    }
    return result;
}

/// <summary>
/// Gets picked-quantity conversion
/// </summary>
/// <param name = "_salesLine">Sales line record</param>
/// <returns>Returns picked qty</returns>
public static Qty pickedQuantity(SalesLine _salesLine)
{
    InventTableModule inventoryModule;

    if (!_salesLine.RecId || !_salesLine.InventTransId)
    {
        throw error("@MET:METPickedQtyValidate");
    }

    inventoryModule = InventTableModule::find(_salesLine.ItemId, ModuleInventPurchSales::Invent);
    if (!inventoryModule.UnitId || !_salesLine.SalesUnit)
    {
        throw error(strFmt("@MET:METMissingInventory",
            curext(), _salesLine.RecId));
    }

    return EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
        _salesLine.ItemId,
        _salesLine.InventDimId,
        InventTransPickedQuantityView::findByInventTransId(_salesLine.InventTransId).Quantity,
        inventoryModule.UnitId,
        _salesLine.SalesUnit,
        NoYes::Yes);
}
